, \"declaration_kind\": \"theorem\", \"mathlib_commit\": \"905b95818eb32af7874a58b427f50c1711a5e96c\", \"source_path\": \"Mathlib/Topology/MetricSpace/HausdorffDimension.lean\", \"source_sha256\": \"fdc61e7f179044cd714058f209b100e51b6f8af69aff295e3ee629ed45dcee31\", \"evidence\": [{\"path\": \"library/M005-0004/library-sources.json\", \"sha256\": \"02903880f5ce05f85354f18a529c8ad2c4c7e5963341d50f8887fa622353dc73\"}]}}}, {\"pointer\": \"nl0.json#/propositions/8\", \"record\": {\"id\": \"M006\", \"kind\": \"mathlib\", \"statement\": \"For every type α with a measurable-space structure m, measure μ on α, countable type β, and family f:β→α→[0,infinity], if every f_i is μ-almost-everywhere measurable, then the nonnegative integral of the pointwise sum equals the sum of the nonnegative integrals: ∫ sum_i f_i dμ = sum_i ∫ f_i dμ. Both sides may be infinity.\", \"definitions\": [], \"binders\": [{\"symbol\": \"α\", \"type\": \"type\"}, {\"symbol\": \"m\", \"type\": \"measurable-space structure on α\"}, {\"symbol\": \"μ\", \"type\": \"measure on (α,m)\"}, {\"symbol\": \"β\", \"type\": \"countable type\"}, {\"symbol\": \"f\", \"type\": \"family β→α→[0,infinity]\"}, {\"symbol\": \"i\", \"type\": \"index in β\"}], \"objects\": [\"α\", \"m\", \"μ\", \"β\", \"f\", \"i\"], \"source\": {\"declaration\": \"MeasureTheory.lintegral_tsum\", \"hypotheses\": [\"α has measurable-space structure m and μ is a measure on it.\", \"The index type β is countable.\", \"For every i, f_i is μ-almost-everywhere measurable.\"], \"statement\": \"For every type α with a measurable-space structure m, measure μ on α, countable type β, and family f:β→α→[0,infinity], if every f_i is μ-almost-everywhere measurable, then the nonnegative integral of the pointwise sum equals the sum of the nonnegative integrals: ∫ sum_i f_i dμ = sum_i ∫ f_i dμ. Both sides may be infinity.\", \"module\": \"Mathlib.MeasureTheory.Integral.Lebesgue.Add\", \"signature\": \"@MeasureTheory.lintegral_tsum : ∀ {α : Type u_1} {β : Type u_2} {m : MeasurableSpace.{u_1} α} {μ : MeasureTheory.Measure.{u_1} α}\\n  [Countable.{u_2 + 1} β] {f : β → α → ENNReal},\\n  (∀ (i : β), AEMeasurable.{u_1, 0} (f i) μ) →\\n    Eq.{1} (∫⁻ (a : α), ∑' (i : β), f i a ∂μ) (∑' (i : β), ∫⁻ (a : α), f i a ∂μ)\", \"declaration_kind\": \"theorem\", \"mathlib_commit\": \"905b95818eb32af7874a58b427f50c1711a5e96c\", \"source_path\": \"Mathlib/MeasureTheory/Integral/Lebesgue/Add.lean\", \"source_sha256\": \"14da3dd3c2692219eec43e91c6b22bb02d5db7f00e03c789661c72dffecf7b4a\", \"evidence\": [{\"path\": \"library/M006-0006/library-sources.json\", \"sha256\": \"bcb31a219df53bbada5177f1f9753fe988cbf091913512919d408c6ea1698767\"}]}}}, {\"pointer\": \"nl0.json#/propositions/9\", \"record\": {\"id\": \"N001\", \"kind\": \"internal\", \"statement\": \"For every natural m, subset A⊆R^m and positive real s, H^s(A)=μH[s](A). Consequently: if s>dim_H(A) then H^s(A)=0; if 0<s<dim_H(A) then H^s(A)=infinity; H^s(A)=0 implies dim_H(A)≤s; H^s(A)=infinity implies dim_H(A)≥s. Dimension is nonnegative, including for the empty set.\", \"objects\": [\"m\", \"A\", \"s\", \"H\", \"μH\", \"dim_H\"], \"definitions\": [\"D001\", \"D002\", \"D003\", \"D004\"], \"binders\": [{\"symbol\": \"m\", \"type\": \"natural number\"}, {\"symbol\": \"A\", \"type\": \"subset of Euclidean R^m\"}, {\"symbol\": \"s\", \"type\": \"positive real number\"}], \"origin\": \"Expansion of the supplied proof in problem.md; see its unique producing inference.\"}}, {\"pointer\": \"nl0.json#/propositions/10\", \"record\": {\"id\": \"N002\", \"kind\": \"internal\", \"statement\": \"D is finite and 0≤D≤n. If n=0, then E=R^0 is a singleton and D=0. For every positive real s and delta, H^s_delta(E) is finite.\", \"objects\": [\"n\", \"E\", \"D\", \"H\", \"s\", \"delta\"], \"definitions\": [\"D001\", \"D002\", \"D004\", \"D007\"], \"binders\": [{\"symbol\": \"s\", \"type\": \"positive real number\"}, {\"symbol\": \"delta\", \"type\": \"positive real number\"}], \"origin\": \"Expansion of the supplied proof in problem.md; see its unique producing inference.\"}}, {\"pointer\": \"nl0.json#/propositions/11\", \"record\": {\"id\": \"N003\", \"kind\": \"internal\", \"statement\": \"dim_H(I)=1. For every a>1, H^a(I)=0, and for every s with 0<s<1, H^s(I)=infinity.\", \"objects\": [\"I\", \"dim_H\", \"H\", \"a\", \"s\"], \"definitions\": [\"D001\", \"D002\", \"D004\", \"D005\", \"D008\"], \"binders\": [{\"symbol\": \"a\", \"type\": \"real number\"}, {\"symbol\": \"s\", \"type\": \"real number\"}], \"origin\": \"Expansion of the supplied proof in problem.md; see its unique producing inference.\"}}, {\"pointer\": \"nl0.json#/propositions/12\", \"record\": {\"id\": \"N004\", \"kind\": \"internal\", \"statement\": \"dim_H(F)≤D+1, and in particular dim_H(F) is finite.\", \"objects\": [\"F\", \"D\", \"dim_H\"], \"definitions\": [\"D004\", \"D006\", \"D007\"], \"binders\": [], \"origin\": \"Expansion of the supplied proof in problem.md; see its unique producing inference.\"}}, {\"pointer\": \"nl0.json#/propositions/13\", \"record\": {\"id\": \"N005\", \"kind\": \"internal\", \"statement\": \"For every real s>0 and delta>0, H^s_delta(E)≤H^(s+1)_delta(F).\", \"objects\": [\"s\", \"delta\", \"E\", \"F\", \"H\"], \"definitions\": [\"D001\", \"D002\", \"D005\", \"D006\"], \"binders\": [{\"symbol\": \"s\", \"type\": \"real number\"}, {\"symbol\": \"delta\", \"type\": \"real number\"}], \"origin\": \"Expansion of the supplied proof in problem.md; see its unique producing inference.\"}}, {\"pointer\": \"nl0.json#/propositions/14\", \"record\": {\"id\": \"N006\", \"kind\": \"internal\", \"statement\": \"If D>0, then dim_H(F)≥D+1.\", \"objects\": [\"D\", \"F\", \"dim_H\"], \"definitions\": [\"D004\", \"D006\", \"D007\"], \"binders\": [], \"origin\": \"Expansion of the supplied proof in problem.md; see its unique producing inference.\"}}, {\"pointer\": \"nl0.json#/propositions/15\", \"record\": {\"id\": \"N007\", \"kind\": \"internal\", \"statement\": \"If D=0, then dim_H(F)